const rows = $input.all().map(item => item.json);
return rows.map(d => {
  const sku = String(d.article ?? '').trim();
  const name = String(d.name ?? '').trim();
  const price = Number(d.price);
  const stock = Number(d.quantity);
  const productUrl = String(d.url ?? '').trim();
  if (!sku || !name || !Number.isFinite(price) || price < 0 || !Number.isInteger(stock) || stock < 0 || !productUrl.startsWith('https://ekt.kz/catalog/')) {
    throw new Error('Invalid product detail for id ' + String(d.id ?? '?'));
  }
  const path = productUrl.slice('https://ekt.kz'.length).split('/').filter(Boolean);
  const category = path.slice(1, -1).join('/') || 'uncategorized';
  const byWarehouse = {};
  for (const store of Array.isArray(d.stores) ? d.stores : []) {
    const warehouse = String(store.name ?? '').trim();
    const quantity = Number(store.quantity);
    if (warehouse && Number.isInteger(quantity) && quantity >= 0) byWarehouse[warehouse] = quantity;
  }
  const attributes = { ...(d.properties && typeof d.properties === 'object' ? d.properties : {}), description: d.description ?? null, image_url: d.image ?? null, source_id: d.id, category_source: 'url_path' };
  return { json: { sku, name, category, price, stock_total: stock, stock_by_warehouse: byWarehouse, attributes, certificate_url: null, product_url: productUrl } };
});
